def test_contract_authority_and_antifarm():
 d=json.loads((ROOT/'data/m243_wanted_bounty_contract.json').read_text()); assert d['authority']['player_wanted']=='server_authoritative'; assert 'repeat_target_diminishing' in d['anti_farm']; assert 'grant_bounty_reward' in d['forbidden_client_actions']; assert set(['npc','admiral','monster','player'])<=set(d['bounty_targets'])
def test_runtime_is_monotonic_and_read_only():
 s=(ROOT/'scripts/progression/m243_wanted_bounty_runtime.gd').read_text();
 for token in ['class_name M243WantedBountyRuntime','if incoming_revision < revision:','LOCAL_PREVIEW','can_client_mutate_wanted() -> bool: return false','can_client_settle_bounty() -> bool: return false','can_client_grant_reward() -> bool: return false','can_client_mutate_honor() -> bool: return false']: assert token in s
def test_factory_ui_and_officer_save_fix():
 f=(ROOT/'scripts/core/procedural_factory.gd').read_text(); ui=(ROOT/'scripts/ui/command_deck.gd').read_text(); gs=(ROOT/'scripts/core/game_state.gd').read_text(); op=(ROOT/'scripts/progression/m242_officer_progression_runtime.gd').read_text(); assert 'M243WantedBountyRuntime.new()' in f and 'wanted_bounty.name = "WantedBounty"' in f; assert 'WANTED & BOUNTIES' in ui and 'M243WantedBountyCatalog.status_card' in ui; assert '"m242_officer_progression"' in gs and 'officer_progression.import_state' in gs; assert 'func export_state()' in op and 'func import_state(state: Dictionary)' in op
def test_convergence_promoted_to_foundation():
 d=json.loads((ROOT/'data/m239_master_convergence_matrix.json').read_text()); by={x['domain']:x for x in d['domains']}; assert by['wanted_bounty']['status']=='FOUNDATION'
